SELECT '== P5b decision_log last 25 ==' AS x;
SELECT timestamp, decision, LEFT(reason,120) AS reason, compositePct, `signal` FROM decision_log WHERE strategyId='4d392a8a-b153-438c-9c0c-1ee547d05572' ORDER BY timestamp DESC LIMIT 25;
SELECT '== P6b queue last 20 ==' AS x;
SELECT createdAt, status, `signal`, signalPct, combinedStrength FROM strategy_signal_queue WHERE strategyId='4d392a8a-b153-438c-9c0c-1ee547d05572' ORDER BY createdAt DESC LIMIT 20;
SELECT '== P6b2 queue totals ==' AS x;
SELECT COUNT(*) AS allRows, MAX(createdAt) AS newest, MAX(updatedAt) AS lastUpdate FROM strategy_signal_queue WHERE strategyId='4d392a8a-b153-438c-9c0c-1ee547d05572';
SELECT '== P6c whole-protocol queue statuses ==' AS x;
SELECT status, COUNT(*) c FROM strategy_signal_queue WHERE protocolId='forex-session-v1' GROUP BY status;
SELECT '== P10b risk/automation settings ==' AS x;
SELECT CONCAT(`key`,' = ',`value`) AS kv FROM global_setting WHERE `key` LIKE 'risk.%' OR `key` LIKE 'automation%' ORDER BY `key`;
SELECT '== P11 trade aggregates ==' AS x;
SELECT COUNT(*) AS trades, SUM(status='closed') AS closedCnt, SUM(pnl>0) AS wins, SUM(pnl<0) AS losses, ROUND(SUM(CASE WHEN status='closed' THEN pnl ELSE 0 END),2) AS netPnl FROM trade WHERE scoringStrategyId='4d392a8a-b153-438c-9c0c-1ee547d05572';
SELECT '== P12 signal_outcome_log EURJPY ==' AS x;
SELECT createdAt, preTradeReady, blockerCount, conflictCount, warningCount FROM signal_outcome_log WHERE symbol='EURJPY' AND protocolId='forex-session-v1' ORDER BY createdAt DESC LIMIT 15;
SELECT '== P13 adjustments for SL-closed ticket 152709863373 ==' AS x;
SELECT adjustedAt, oldSl, newSl, LEFT(reason,100) AS r FROM stop_adjustment WHERE tradeTicket='152709863373' ORDER BY adjustedAt;
